const MAX_SIZE = 10 * 1024 * 1024;
const ALLOWED_EXT = ["tex", "pdf"];

const item = $input.item;
const bin = item.binary?.data;
const candidateId = item.json.candidate_id;

if (!bin) {
  return [{
    json: {
      valid: false,
      errors: ["No file found in binary property data"],
      extension: null,
      candidate_id: candidateId
    }
  }];
}

const fileName = bin.fileName || "";
const ext = (fileName.split(".").pop() || "").toLowerCase();
const errors = [];

const isDocx = ext === "docx";

if (isDocx) {
  errors.push(
    "DOCX not implemented in this version (optional per brief) - please supply .tex or .pdf"
  );
} else if (!ALLOWED_EXT.includes(ext)) {
  errors.push("Unsupported extension: ." + ext);
}

// Get the REAL binary bytes from n8n
let buf;

try {
  buf = await this.helpers.getBinaryDataBuffer(0, "data");
} catch (e) {
  errors.push("Could not read uploaded file binary: " + e.message);
}

const size = buf ? buf.length : 0;

if (size > MAX_SIZE) {
  errors.push("File exceeds " + MAX_SIZE + " bytes");
}

if (size === 0) {
  errors.push("File is empty");
}

// Real content/signature validation
if (buf && errors.length === 0) {

  if (ext === "pdf") {
    const head = buf.slice(0, 5).toString("utf-8");

    if (head !== "%PDF-") {
      errors.push(
        "File content does not match PDF signature (expected %PDF- header) - real content type does not match extension"
      );
    }

  } else if (ext === "tex") {
    const headText = buf
      .slice(0, Math.min(buf.length, 20000))
      .toString("utf-8");

    if (
      !headText.includes("\\documentclass") &&
      !headText.includes("\\begin{document}")
    ) {
      errors.push(
        "File content does not look like LaTeX source (no documentclass or begin document found) - real content type does not match extension"
      );
    }
  }
}

const valid = errors.length === 0 && !isDocx;

return [{
  json: {
    valid,
    errors,
    extension: ext,
    candidate_id: candidateId
  },
  binary: item.binary
}];

const item = $input.item;
const b64 = item.binary.data.data;
let tex = Buffer.from(b64, "base64").toString("utf-8");
tex = tex.split("\\begin{document}")[1] || tex;
tex = tex.replace("\\end{document}", "");
tex = tex.replace(/(?<!\\)%.*$/gm, "");
tex = tex.replace(/\\(sub)*section\*?\{([^}]*)\}/g, "\n\n## $2\n");
tex = tex.replace(/\\begin\{(itemize|enumerate)\}/g, "");
tex = tex.replace(/\\end\{(itemize|enumerate)\}/g, "");
tex = tex.replace(/\\item\s*/g, "- ");
tex = tex.replace(/\\[a-zA-Z]+\*?(\[[^\]]*\])?\{([^{}]*)\}/g, "$2");
tex = tex.replace(/\\[a-zA-Z]+\*?/g, "");
return [{ json: { raw_text: tex.trim(), candidate_id: item.json.candidate_id } }];

const item = $input.item;
const text = item.json.text || item.json.data || "";
return [{ json: { raw_text: String(text).trim(), candidate_id: item.json.candidate_id }, binary: item.binary }];

const REQUIRED = ["candidate_name","email","experience_years","job_titles","preferred_roles","technical_skills","programming_languages","frameworks","tools","keywords","education"];
const ARRAY_FIELDS = ["job_titles","preferred_roles","technical_skills","programming_languages","frameworks","tools","keywords","education"];
const resp = $input.item.json;
let text = "";
if (resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0] && resp.candidates[0].content.parts[0].text) { text = resp.candidates[0].content.parts[0].text; }
let data = null;
let parseError = null;
try { data = JSON.parse(text); } catch (e) { parseError = e.message; }
const errors = [];
if (parseError) { errors.push("Invalid JSON: " + parseError); }
const candidateId = $("Prepared Text").item.json.candidate_id;
const rawText = $("Prepared Text").item.json.raw_text;
if (data) {
  for (const f of REQUIRED) { if (data[f] === undefined) { errors.push("Missing field: " + f); } }
  for (const f of ARRAY_FIELDS) { if (data[f] !== undefined && !Array.isArray(data[f])) { errors.push(f + " must be array"); } }
  if (data.experience_years !== undefined && typeof data.experience_years !== "number") { errors.push("experience_years must be number"); }
  if (data.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) { errors.push("email format invalid"); }

  const rawLower = (rawText || "").toLowerCase();
  const PLACEHOLDER_NAMES = ["john doe", "jane doe", "john smith", "jane smith"];
  const PLACEHOLDER_EMAILS = ["example.com", "test@example.com", "johndoe@example.com", "janedoe@example.com", "user@example.com"];
  const PLACEHOLDER_GENERIC = ["n/a", "not available", "not specified", "unknown", "tbd"];
  const SYNONYMS = { "js": "javascript", "javascript": "js", "postgres": "postgresql", "postgresql": "postgres", "node": "node.js", "nodejs": "node.js", "node.js": "node", "py": "python", "k8s": "kubernetes", "golang": "go" };

  function normalizeToken(s) { return (s || "").toLowerCase().trim(); }
  function isGroundedToken(token) {
    const t = normalizeToken(token);
    if (!t) return true;
    if (rawLower.indexOf(t) !== -1) return true;
    const syn = SYNONYMS[t];
    if (syn && rawLower.indexOf(syn) !== -1) return true;
    return false;
  }
  function isPlaceholder(value, list) {
    const v = normalizeToken(value);
    return list.some(function(p) { return v === p || v.indexOf(p) !== -1; });
  }

  if (data.candidate_name && data.candidate_name.trim()) {
    if (isPlaceholder(data.candidate_name, PLACEHOLDER_NAMES)) {
      errors.push("GROUNDING: candidate_name looks like a placeholder value: " + data.candidate_name);
    } else if (!isGroundedToken(data.candidate_name)) {
      errors.push("GROUNDING: candidate_name not found in source text: " + data.candidate_name);
    }
  }

  if (data.email && data.email.trim()) {
    const emailLower = normalizeToken(data.email);
    if (isPlaceholder(emailLower, PLACEHOLDER_EMAILS)) {
      errors.push("GROUNDING: email looks like a placeholder value: " + data.email);
    } else if (rawLower.indexOf(emailLower) === -1) {
      errors.push("GROUNDING: email not found verbatim in source text: " + data.email);
    }
  }

  if (data.phone && String(data.phone).trim()) {
    const phoneDigits = String(data.phone).replace(/\D/g, "");
    const rawDigitRuns = (rawText || "").match(/[\d][\d\s\-().]{5,}/g) || [];
    const rawDigitSets = rawDigitRuns.map(function(s) { return s.replace(/\D/g, ""); });
    const matched = phoneDigits.length >= 7 && rawDigitSets.some(function(d) { return d.indexOf(phoneDigits) !== -1 || phoneDigits.indexOf(d) !== -1; });
    if (!matched) { errors.push("GROUNDING: phone not found in source text (normalized digits): " + data.phone); }
  }

  const GROUNDED_ARRAY_FIELDS = ["job_titles", "technical_skills", "programming_languages", "frameworks", "tools", "certifications"];
  for (const field of GROUNDED_ARRAY_FIELDS) {
    const arr = data[field];
    if (Array.isArray(arr)) {
      for (const item of arr) {
        if (isPlaceholder(item, PLACEHOLDER_GENERIC)) {
          errors.push("GROUNDING: " + field + " contains a placeholder value: " + item);
        } else if (!isGroundedToken(item)) {
          errors.push("GROUNDING: " + field + " item not supported by source text: " + item);
        }
      }
    }
  }

  if (Array.isArray(data.education)) {
    for (const edu of data.education) {
      if (edu && edu.institution && !isGroundedToken(edu.institution)) { errors.push("GROUNDING: education institution not supported by source text: " + edu.institution); }
      if (edu && edu.degree && !isGroundedToken(edu.degree)) { errors.push("GROUNDING: education degree not supported by source text: " + edu.degree); }
      if (edu && edu.field && !isGroundedToken(edu.field)) { errors.push("GROUNDING: education field not supported by source text: " + edu.field); }
    }
  }

  if (Array.isArray(data.projects)) {
    for (const proj of data.projects) {
      if (proj && proj.name && !isGroundedToken(proj.name)) { errors.push("GROUNDING: project name not supported by source text: " + proj.name); }
      if (proj && Array.isArray(proj.technologies)) {
        for (const tech of proj.technologies) {
          if (!isGroundedToken(tech)) { errors.push("GROUNDING: project technology not supported by source text: " + tech); }
        }
      }
    }
  }
}
return [{ json: { valid: errors.length === 0, errors: errors, data: data, candidate_id: candidateId, raw_text: rawText } }];

